css:
[data-t3-part="app-shell"] { accent-color:#ff4fd8; }
[data-t3-part="main"] { background-color:#080a10; }
[data-t3-part="sidebar"] {
 background-color:#0b0e18;
 background-image:repeating-linear-gradient(0deg,transparent 0px,transparent 3px,rgba(50,232,255,.025) 3px,rgba(50,232,255,.025) 4px);
 border-right-color:#244858;
 box-shadow:inset -1px 0 0 #32e8ff22;
}
[data-t3-part="chat-header"], [data-t3-part="sidebar-header"] {
 background-color:#0e111c;
 background-image:repeating-linear-gradient(0deg,transparent 0px,transparent 3px,#32e8ff05 3px,#32e8ff05 4px);
 border-bottom:1px solid #32e8ff55;
 box-shadow:0 1px 10px #32e8ff12;
 text-shadow:1px 0 #ff4fd855,-1px 0 #32e8ff66;
}
[data-t3-part="sidebar-section-header"] {
 color:#7cefff;
 font-family:ui-monospace,SFMono-Regular,Consolas,monospace;
 letter-spacing:.075em;
 text-transform:uppercase;
 text-shadow:1px 0 #ff4fd866,-1px 0 #32e8ff55;
}
[data-t3-part="thread-row"] { border-radius:3px; }
[data-t3-part="thread-row"][aria-current="page"] {
 background-color:#23152b;
 border-color:#ff4fd888;
 box-shadow:inset 2px 0 #ff4fd8,inset 0 0 12px #ff4fd80a,0 0 9px #ff4fd815;
 background-image:linear-gradient(135deg,#32e8ff 0 4px,transparent 4.5px);
}
[data-t3-part="thread-row"]:hover { box-shadow:inset 2px 0 #32e8ff; }
[data-t3-part="project-name"] { color:#82edff; }
[data-t3-part="composer"] {
 border:1px solid #32e8ff66;
 border-radius:12px 3px 12px 3px;
 corner-shape:bevel;
 background-color:#10141f;
 background-image:linear-gradient(135deg,#32e8ff44 0 7px,transparent 7.5px),linear-gradient(315deg,#ff4fd844 0 7px,transparent 7.5px);
 box-shadow:0 0 14px #32e8ff12,0 0 25px #ff4fd80b;
}
[data-t3-part="composer"]:focus-within { border-color:#32e8ff; box-shadow:0 0 0 1px #32e8ff44,0 0 18px #32e8ff20; }
[data-t3-part="user-message-bubble"] {
 border:1px solid #ff4fd84d;
 border-radius:12px 3px 12px 3px;
 corner-shape:bevel;
 background-color:#211426;
 background-image:linear-gradient(135deg,#ff4fd833 0 6px,transparent 6.5px);
 box-shadow:0 0 12px #ff4fd80b;
}
[data-t3-part="assistant-message"] { color:#e5eaf4; }
[data-t3-part="right-panel"] { border-left-color:#32e8ff55; }
[data-t3-part="terminal-drawer"] { border-top:1px solid #ff4fd877; box-shadow:0 -2px 12px #ff4fd80d; }
[data-t3-part="sidebar-footer"] { border-top-color:#244858; }

/* Neon Circuit: amplified sidebar treatment. */
[data-t3-part="thread-title"] {
 color:#ff69df;
 font-size:18px;
 font-weight:800;
 line-height:1.35;
 letter-spacing:.015em;
 white-space:normal;
 overflow-wrap:anywhere;
 text-shadow:1.5px 0 #32e8ff,0 0 7px #ff4fd877,0 0 17px #ff4fd844;
}
[data-t3-part="thread-body"] { height:auto; min-width:0; }
[data-t3-part="thread-row"]:not([data-t3-variant="slim"]) {
 padding-top:32px;
 padding-bottom:10px;
}
[data-t3-part="thread-row"]:not([data-t3-variant="slim"]) [data-t3-part="thread-project"] {
 display:inline-block;
 position:absolute;
 top:6px;
 left:10px;
 right:auto;
 max-width:calc(100% - 24px);
 overflow:hidden;
 text-overflow:ellipsis;
 white-space:nowrap;
 padding:2px 9px;
 border:1px solid #32e8ffb3;
 border-radius:999px;
 background:#11313d;
 color:#a1f5ff;
 font-family:ui-monospace,SFMono-Regular,Consolas,monospace;
 font-size:10px;
 font-weight:750;
 line-height:1.4;
 letter-spacing:.04em;
 text-shadow:0 0 6px #32e8ff66;
 box-shadow:0 0 7px #32e8ff40,inset 0 0 7px #32e8ff15;
}
[data-t3-part="thread-row"][aria-current="page"] [data-t3-part="thread-project"] {
 border-color:#ff69df;
 background:#34132f;
 color:#ffb9ef;
 box-shadow:0 0 9px #ff4fd84d,inset 0 0 7px #ff4fd81a;
}
[data-t3-part="sidebar"],
[data-t3-part="sidebar-header"],
[data-t3-part="sidebar-toolbar"],
[data-t3-part="sidebar-footer"],
[data-t3-part="thread-row"] {
 background-image:repeating-linear-gradient(to bottom,transparent 0px,transparent 3px,rgba(50,232,255,.065) 3px,rgba(50,232,255,.065) 4px);
}
[data-t3-part="thread-row"][aria-current="page"] {
 background-image:repeating-linear-gradient(to bottom,transparent 0px,transparent 3px,rgba(50,232,255,.065) 3px,rgba(50,232,255,.065) 4px),linear-gradient(135deg,#32e8ff 0 4px,transparent 4.5px);
}

/* Settled rows keep the neon treatment within their own content-sized row. */
[data-t3-part="thread-item"][data-t3-variant="slim"] {
 height:auto;
 padding-block:2px;
}
[data-t3-part="thread-row"][data-t3-variant="slim"] {
 height:auto;
 min-height:32px;
 padding-block:6px;
 align-items:center;
}
[data-t3-part="thread-row"][data-t3-variant="slim"] [data-t3-part="thread-title"] {
 min-width:0;
 font-size:13px;
 font-weight:700;
 line-height:1.4;
 white-space:normal;
 overflow-wrap:anywhere;
 overflow:visible;
 text-overflow:clip;
 -webkit-line-clamp:unset;
}
[data-t3-part="thread-row"][data-t3-variant="slim"] [data-t3-part="thread-status"] {
 flex-shrink:0;
}
[data-t3-part="thread-row"][data-t3-variant="slim"] [data-t3-part="thread-project"] {
 display:none;
}
